function me = ElementLHS4ConMass_FR(nnpe,nqptv,wtq,qpmetric,bigN,detj)%% called by Ormonics and FitOrientationDistributionWithHarmonics% forms elemental   mass matrix for consistent penalty for fundamental% region of orientation spaceme = zeros(nnpe,nnpe);                                       for   k=1:1:nqptv       bigNqp = bigN(:,k)';                                      xkfac(k)=wtq(k)*detj(k)*qpmetric(k);    me = me + xkfac(k)*(bigNqp' * bigNqp);      end